-- Place holder: The Database owner will replace these provisional local tables and migrations.
CREATE TABLE IF NOT EXISTS mutation_lock (id INT PRIMARY KEY);
MERGE INTO mutation_lock (id) KEY(id) VALUES (1);
CREATE TABLE IF NOT EXISTS app_account (id VARCHAR(40) PRIMARY KEY, display_name VARCHAR(120) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, account_status VARCHAR(30) NOT NULL, failed_count INT DEFAULT 0 NOT NULL, lock_until VARCHAR(40));
CREATE TABLE IF NOT EXISTS product_stock (sku VARCHAR(60) PRIMARY KEY, product_name VARCHAR(150) NOT NULL, physical_stock INT NOT NULL CHECK(physical_stock>=0), reserved_stock INT NOT NULL CHECK(reserved_stock>=0), unavailable_stock INT NOT NULL CHECK(unavailable_stock>=0), low_threshold INT NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_order (id VARCHAR(60) PRIMARY KEY, order_reference VARCHAR(60) UNIQUE NOT NULL, client_id VARCHAR(60) NOT NULL, order_status VARCHAR(40) NOT NULL, payment_accepted BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_detail (id VARCHAR(60) PRIMARY KEY, order_id VARCHAR(60) NOT NULL REFERENCES delivery_order(id), version_no INT NOT NULL, recipient_name VARCHAR(120) NOT NULL, phone VARCHAR(80) NOT NULL, address_text VARCHAR(600) NOT NULL, UNIQUE(order_id,version_no));
CREATE TABLE IF NOT EXISTS order_item (id VARCHAR(60) PRIMARY KEY, order_id VARCHAR(60) NOT NULL REFERENCES delivery_order(id), sku VARCHAR(60) NOT NULL REFERENCES product_stock(sku), quantity INT NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS delivery_package (id VARCHAR(60) PRIMARY KEY, order_id VARCHAR(60) UNIQUE NOT NULL REFERENCES delivery_order(id), qr_code VARCHAR(80) UNIQUE NOT NULL, custody VARCHAR(30) NOT NULL, holder_id VARCHAR(40) REFERENCES app_account(id), responsible_id VARCHAR(40) REFERENCES app_account(id), detail_id VARCHAR(60) NOT NULL REFERENCES delivery_detail(id), hold_reason VARCHAR(300), last_pickup_id VARCHAR(60), last_return_id VARCHAR(60), approved_instruction_id VARCHAR(60), retry_approved BOOLEAN DEFAULT FALSE NOT NULL, failed_return BOOLEAN DEFAULT FALSE NOT NULL, version_no BIGINT DEFAULT 0 NOT NULL);
CREATE TABLE IF NOT EXISTS stock_allocation (package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), sku VARCHAR(60) NOT NULL REFERENCES product_stock(sku), quantity INT NOT NULL CHECK(quantity>=0), PRIMARY KEY(package_id,sku));
CREATE TABLE IF NOT EXISTS pickup_list (id VARCHAR(60) PRIMARY KEY, qr_code VARCHAR(80) UNIQUE NOT NULL, list_status VARCHAR(30) NOT NULL, created_at VARCHAR(40) NOT NULL, created_by VARCHAR(60) NOT NULL, claimed_by VARCHAR(40) REFERENCES app_account(id), claimed_at VARCHAR(40), last_activity_at VARCHAR(40));
CREATE TABLE IF NOT EXISTS pickup_item (list_id VARCHAR(60) NOT NULL REFERENCES pickup_list(id), package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), collection_outcome VARCHAR(30) NOT NULL, reason VARCHAR(40), internal_note VARCHAR(600), collected_at VARCHAR(40), PRIMARY KEY(list_id,package_id));
CREATE TABLE IF NOT EXISTS pickup_cycle (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), list_id VARCHAR(60) NOT NULL REFERENCES pickup_list(id), worker_id VARCHAR(40) NOT NULL REFERENCES app_account(id), collected_at VARCHAR(40) NOT NULL, approval_id VARCHAR(60));
CREATE TABLE IF NOT EXISTS delivery_attempt (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), worker_id VARCHAR(40) NOT NULL REFERENCES app_account(id), pickup_id VARCHAR(60) NOT NULL REFERENCES pickup_cycle(id), detail_id VARCHAR(60) NOT NULL REFERENCES delivery_detail(id), started_at VARCHAR(40) NOT NULL, ended_at VARCHAR(40), outcome VARCHAR(30) NOT NULL, reason VARCHAR(40), internal_note VARCHAR(600));
CREATE TABLE IF NOT EXISTS delivery_proof (id VARCHAR(60) PRIMARY KEY, attempt_id VARCHAR(60) NOT NULL REFERENCES delivery_attempt(id), worker_id VARCHAR(40) NOT NULL REFERENCES app_account(id), proof_type VARCHAR(30) NOT NULL, file_name VARCHAR(100) NOT NULL, content_type VARCHAR(50) NOT NULL, byte_count BIGINT NOT NULL, sha256 VARCHAR(64) NOT NULL, created_at VARCHAR(40) NOT NULL, used_for_outcome BOOLEAN DEFAULT FALSE NOT NULL);
CREATE TABLE IF NOT EXISTS return_receipt (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), pickup_id VARCHAR(60) NOT NULL REFERENCES pickup_cycle(id), attempt_id VARCHAR(60) REFERENCES delivery_attempt(id), reported_by VARCHAR(40) NOT NULL REFERENCES app_account(id), reason VARCHAR(600) NOT NULL, receipt_status VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, received_at VARCHAR(40), received_by VARCHAR(60), receipt_condition VARCHAR(30));
CREATE TABLE IF NOT EXISTS return_line (return_id VARCHAR(60) NOT NULL REFERENCES return_receipt(id), sku VARCHAR(60) NOT NULL REFERENCES product_stock(sku), actual_quantity INT NOT NULL CHECK(actual_quantity>=0), unusable_quantity INT NOT NULL CHECK(unusable_quantity>=0), PRIMARY KEY(return_id,sku));
CREATE TABLE IF NOT EXISTS client_instruction (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), return_id VARCHAR(60) NOT NULL REFERENCES return_receipt(id), detail_id VARCHAR(60) NOT NULL REFERENCES delivery_detail(id), version_no INT NOT NULL, instruction_type VARCHAR(30) NOT NULL, instruction_status VARCHAR(30) NOT NULL, created_at VARCHAR(40) NOT NULL, resolved_at VARCHAR(40), resolved_by VARCHAR(60));
CREATE TABLE IF NOT EXISTS discrepancy_case (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), source_id VARCHAR(60) NOT NULL, case_status VARCHAR(40) NOT NULL, condition_code VARCHAR(40) NOT NULL, reported_by VARCHAR(60) NOT NULL, created_at VARCHAR(40) NOT NULL, safe_detail VARCHAR(600) NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movement (id VARCHAR(60) PRIMARY KEY, sku VARCHAR(60) NOT NULL REFERENCES product_stock(sku), package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), source_id VARCHAR(60) NOT NULL, movement_type VARCHAR(30) NOT NULL, physical_delta INT NOT NULL, reserved_delta INT NOT NULL, unavailable_delta INT NOT NULL, actor_id VARCHAR(60) NOT NULL, event_at VARCHAR(40) NOT NULL, UNIQUE(source_id,sku));
CREATE TABLE IF NOT EXISTS custody_event (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), source_id VARCHAR(60) NOT NULL, event_type VARCHAR(40) NOT NULL, from_holder VARCHAR(60), to_holder VARCHAR(60), actor_id VARCHAR(60) NOT NULL, event_at VARCHAR(40) NOT NULL, UNIQUE(source_id,event_type));
CREATE TABLE IF NOT EXISTS audit_event (id VARCHAR(60) PRIMARY KEY, actor_id VARCHAR(60) NOT NULL, action_name VARCHAR(80) NOT NULL, target_id VARCHAR(80) NOT NULL, safe_detail VARCHAR(600) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS security_event (id VARCHAR(60) PRIMARY KEY, account_id VARCHAR(40), event_type VARCHAR(40) NOT NULL, event_result VARCHAR(30) NOT NULL, occurred_at VARCHAR(40) NOT NULL, ip_address VARCHAR(100), device_info VARCHAR(300));
CREATE TABLE IF NOT EXISTS notification_outbox (id VARCHAR(60) PRIMARY KEY, actor_id VARCHAR(60) NOT NULL, client_id VARCHAR(60), package_id VARCHAR(60), event_type VARCHAR(60) NOT NULL, safe_message VARCHAR(600) NOT NULL, created_at VARCHAR(40) NOT NULL, is_read BOOLEAN DEFAULT FALSE NOT NULL, transport_status VARCHAR(40) DEFAULT 'PLACE_HOLDER' NOT NULL);
CREATE TABLE IF NOT EXISTS operation_result (actor_id VARCHAR(60) NOT NULL, action_name VARCHAR(120) NOT NULL, request_id VARCHAR(40) NOT NULL, payload_hash VARCHAR(64) NOT NULL, result_json CLOB NOT NULL, created_at VARCHAR(40) NOT NULL, PRIMARY KEY(actor_id,action_name,request_id));
CREATE TABLE IF NOT EXISTS retained_summary (id VARCHAR(60) PRIMARY KEY, package_id VARCHAR(60) NOT NULL REFERENCES delivery_package(id), worker_id VARCHAR(40) NOT NULL REFERENCES app_account(id), outcome VARCHAR(30) NOT NULL, event_at VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_status (id VARCHAR(60) PRIMARY KEY, last_run_at VARCHAR(40), removed_proofs INT DEFAULT 0 NOT NULL, removed_attempts INT DEFAULT 0 NOT NULL, orphan_count INT DEFAULT 0 NOT NULL, last_error VARCHAR(300));
CREATE INDEX IF NOT EXISTS idx_attempt_package ON delivery_attempt(package_id);
CREATE INDEX IF NOT EXISTS idx_return_package ON return_receipt(package_id);
CREATE INDEX IF NOT EXISTS idx_pickup_package ON pickup_item(package_id);
